      "passage_id": "passage_1b41adb6463d2a12a18c0a7f",
      "supporting_excerpt": "The types of products that meet the definition of subject merchandise include but are not limited to, the aluminum extrusion portions of vehicle roof rails and sun/moon roof framing... electric vehicle battery trays, heat sinks...","relevance_explanation": "Explicitly lists 'electric vehicle battery trays' as subject merchandise under Aluminum Extrusions AD/CVD orders.","company_applicability": "not_established","temporal_status": "source_reports_effective_as_of_source_date"
    },
    {
